pragma circom 2.2.3;

include "../range.circom";

// age is private; threshold is public. Both are bytes (0..255).
component main {public [threshold]} = AgeAtLeast(8);

pragma circom 2.2.3;

include "circomlib/circuits/bitify.circom";
include "circomlib/circuits/comparators.circom";

// Constrains `age` and `threshold` to be n-bit unsigned integers with
// age >= threshold.
template AgeAtLeast(n) {
    // LessThan-family comparators are only sound for n <= 252.
    assert(n > 0 && n <= 252);

    signal input age;
    signal input threshold;

    // Range checks: both values must lie in [0, 2^n - 1]. These are also the
    // preconditions for GreaterEqThan(n) to be sound.
    _ <== Num2Bits(n)(age);
    _ <== Num2Bits(n)(threshold);

    signal ok <== GreaterEqThan(n)([age, threshold]);
    ok === 1;
}

{
  "name": "range-circuit",
  "version": "1.0.0",
  "private": true,
  "description": "Prove a private 8-bit value is at least a public 8-bit threshold",
  "devDependencies": {
    "circomlib": "2.0.5",
    "snarkjs": "0.7.6"
  }
}
